import {getStaticFiles} from 'remotion';
import edit from './edit.json';
import generated from './generated/voice.json';
import {beats, seconds} from './theme';

// Sound for the film: one score, one effects stem and one clip per spoken
// line, all generated by scripts/audio from the cue sheet in src/edit.json.

export const AUDIO_FILES = {
	score: 'audio/score.mp3',
	sfx: 'audio/sfx.mp3',
	voice: (id: string) => `audio/voice/${id}.mp3`,
};

// Mix levels (1 = file as mastered). These were set by measuring the rendered
// mix: about -15 LUFS integrated with the true peak just under -1 dBTP. If you
// change one, re-measure (see CLAUDE.md, "Checking changes").
export const MIX = {
	score: 0.95,
	/** Score level while a line is being spoken (about 9 dB under the voice). */
	scoreUnderVoice: 0.42,
	sfx: 1.1,
	voice: 1.36,
};

const clips = generated.clips as Record<string, {seconds: number} | undefined>;

/** Spoken lines with their start frame and length in frames. */
export const VOICE_CUES = edit.voice.map((cue) => {
	const length = clips[cue.id]?.seconds ?? cue.maxSeconds;
	return {
		id: cue.id,
		text: cue.text,
		from: beats(cue.at),
		durationInFrames: seconds(length),
	};
});

/** True when a file exists under assets/, so missing audio never breaks a render. */
export const hasAsset = (name: string): boolean => getStaticFiles().some((f) => f.name === name);

/** Score volume at `frame`: dips smoothly under each spoken line. */
export const scoreVolume = (frame: number, ducking: boolean): number => {
	if (!ducking) {
		return MIX.score;
	}
	const FADE = 8;
	let duck = 0;
	for (const cue of VOICE_CUES) {
		const start = cue.from - FADE;
		const end = cue.from + cue.durationInFrames;
		if (frame < start || frame > end + FADE) {
			continue;
		}
		const amount = Math.min(1, (frame - start) / FADE, (end + FADE - frame) / FADE);
		duck = Math.max(duck, amount);
	}
	return MIX.score + (MIX.scoreUnderVoice - MIX.score) * duck;
};
